import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run } from '../src/jobs/subscribe.js';

// #9: the 500 body is shown on the scheduler's admin screen; it must not carry the internal error text.
test('subscribe: a database error is a 500 with a fixed message', () => {
  const res = run({ db: { addSubscriber: () => { throw new Error('db down at 10.0.0.5'); } }, email: 'a@example.com' });
  assert.equal(res.status, 500);
  assert.equal(res.body.error, 'internal error');
});
